local ADDON_NAME, ns = ...

-- Terrain padding (build step 5): the real minimap terrain around Blizzard's square minimap, at its
-- exact scale, filling the rest of the map frame when it isn't square (the Height setting). Design:
-- docs/design/terrain-map.md ("Terrain core", "Minimap padding").
--
-- The tiles are the minimap's own ground textures, loaded by FileDataID (Data/Tiles.lua, generated by
-- tools/terrain.py; on Forever a path string doesn't load them). Each continent is a 64 x 64 grid of
-- 533.33-yard tiles: col = 32 - worldY / 533.33, row = 32 - worldX / 533.33, from UnitPosition (world
-- yards; +x north, +y west). So a world point's offset from the player on screen is
-- right = (playerY - y) * scale, up = (x - playerX) * scale, scale in pixels per yard.
--
-- How it's drawn:
--   - A clipping frame of ours over the whole map frame, under Blizzard's minimap (which draws its
--     square on top); a dark fill where there's no terrain (open sea).
--   - Tiles are textures in a fixed pool, one per grid slot: tile (c, r) always lives in slot
--     (c % SLOTS, r % SLOTS), so moving across a tile edge re-textures only the row or column coming in,
--     and SetTexture is skipped when a slot already holds that tile. The visible tiles plus a ring of
--     one around them are kept loaded (the warm ring: a tile is textured before it scrolls into view).
--   - Every frame only positions change: the pixels-per-yard scale (Blizzard's zoom, indoors and out,
--     C_Minimap.GetViewRadius) and the player's position. The set of tiles is worked out again only when
--     the player crosses a tile edge or the scale changes.
--   - Off a continent in the table (instances, unknown maps), the padding is just the dark fill.
--   - Rotate Minimap on: every tile turns with the player's facing, as BubbleQuest's minimap areas do,
--     and fills the corners Blizzard's turned square leaves empty.
--   - Nothing at all while the map is square and north-up: Blizzard's minimap covers it all then.
--   - One ground, no seam: while our tiles are drawn, Blizzard's ground is off
--     (C_Minimap.SetDrawGroundTextures(false)) and ours shows through the minimap under its blips, as
--     Blizzard's own HybridMinimap does (Blizzard_HybridMinimap.lua:44; its frame sits a strata under
--     the minimap, as ours does). Its shading differed from the raw tiles: the edge showed (review).
--     Indoors (caves, buildings: interior maps we don't have yet), off our data, or while HybridMinimap
--     is up (it owns the setting then), Blizzard's ground is on.

local TILE_YARDS = 1600 / 3   -- 533.33
local GRID = 64
local FILL = ns.SEA

local Terrain = {
  active = false,
  zoom = 1,     -- the view reaches this many times further than Blizzard's minimap (Zoom.lua's overview)
  force = false,  -- drawn whatever the shape and zoom: BubbleMap's own map is showing (Zoom.lua)
  loaded = 0,   -- SetTexture calls (for /bmap)
  failed = 0,   -- SetTexture calls that returned false
}
ns.Terrain = Terrain

local clip, holder, fill
local art  -- the "Map art" style's view (Art.lua)
local slots = {}        -- [slotKey] = texture
local slotTile = {}     -- [slotKey] = tile key it holds
local slotCol, slotRow = {}, {}  -- [texture] = the grid column and row it shows
local lastCol, lastRow, lastMap, lastSpan

local function rotating()
  -- apiguard: allow the argument is a constant string, never a secret value
  return GetCVarBool("rotateMinimap") and not C_Minimap.IsRotateMinimapIgnored()
end

-- Pixels (in `clip`'s units) per yard: Blizzard's minimap shows GetViewRadius yards from its centre to
-- its edge.
local lastRadius  -- the last view radius the game reported (BubbleMap's own map hides the minimap)

local function scale()
  local radius = C_Minimap.GetViewRadius()
  if radius and radius > 0 then
    lastRadius = radius
  else
    radius = lastRadius
  end
  if not radius then
    return nil
  end
  local half = Minimap:GetWidth() / 2 * Minimap:GetEffectiveScale() / clip:GetEffectiveScale()
  return half / (radius * Terrain.zoom)
end

local function slot(c, r, span)
  local key = (c % span) * span + (r % span)
  local t = slots[key]
  if not t then
    t = holder:CreateTexture(nil, "BACKGROUND", nil, 1)
    t:SetSnapToPixelGrid(false)
    t:SetTexelSnappingBias(0)
    slots[key] = t
  end
  return t, key
end

-- Which tiles: every tile the frame shows, plus a ring of one. Re-textures only slots whose tile changed.
local function assign(tiles, col, row, span)
  local half = math.floor(span / 2)
  local used = {}
  for c = col - half, col - half + span - 1 do
    for r = row - half, row - half + span - 1 do
      local t, key = slot(c, r, span)
      used[key] = true
      local tileKey = (c >= 0 and c < GRID and r >= 0 and r < GRID) and (c * GRID + r) or nil
      local fileID = tileKey and tiles[tileKey]
      if slotTile[key] ~= tileKey then
        slotTile[key] = tileKey
        if fileID then
          Terrain.loaded = Terrain.loaded + 1
          if not t:SetTexture(fileID) then
            Terrain.failed = Terrain.failed + 1
          end
        end
      end
      slotCol[t], slotRow[t] = c, r
      t:SetShown(fileID ~= nil)
    end
  end
  for key, t in pairs(slots) do
    if not used[key] then
      t:Hide()
      slotTile[key] = nil
    end
  end
end

-- Blizzard's ground: off while ours covers it (see the header). Only set on a change.
local groundOff = false
local function blizzardGround(on)
  local hybrid = rawget(_G, "HybridMinimap")
  if hybrid and hybrid:IsShown() then
    groundOff = false  -- HybridMinimap's own; it turns ground back on when it hides
    return
  end
  if groundOff == not on then
    return
  end
  groundOff = not on
  C_Minimap.SetDrawGroundTextures(on)
end

local function hideTiles()
  for _, t in pairs(slots) do
    t:Hide()
  end
  wipe(slotTile)
  lastCol, lastRow, lastMap, lastSpan = nil, nil, nil, nil
end

-- The angle the ground turns by: the player's facing with Rotate Minimap on (BubbleQuest's
-- MinimapAreas turns its areas the same way), else 0. nil when it can't be known (no facing).
local function angle()
  if not rotating() then
    return 0
  end
  return GetPlayerFacing()
end

local function update()
  local outer = ns.Minimap.outer
  local turn = angle()
  -- Square and north-up, Blizzard's minimap covers the whole frame. Rotating, its square ground image
  -- turns and leaves the corners empty (seen in game): ours fills them, so the layer is on then too.
  local square = math.abs(outer:GetWidth() - outer:GetHeight()) < 1
  -- Only the contents hide: `clip` runs this every frame, and a hidden frame gets no OnUpdate, so
  -- hiding it once (square, north-up at login) stopped the padding for good (seen in game: Rotate
  -- Minimap turned on later left the corners empty).
  -- Overview (zoom above 1): Blizzard's minimap is faded out and ours is the whole map.
  -- Our map (Zoom.lua's force): ours is the whole map, whatever its shape or zoom.
  local on = not square or turn ~= 0 or Terrain.zoom ~= 1 or Terrain.force
  fill:SetShown(on)
  holder:SetShown(on)
  if not on then
    blizzardGround(true)
    return
  end
  local px, py, _, mapID = UnitPosition("player")
  local tiles = mapID and ns.Tiles.maps[mapID]
  local s = scale()
  if not (px and py and tiles and s and turn) or IsIndoors() then
    blizzardGround(true)
    if lastMap then
      hideTiles()
    end
    art:Hide()
    return
  end
  blizzardGround(false)

  -- The "Map art" style: the world map's painted art instead of our tiles (Art.lua).
  if ns.DB.mapStyle == "art" then
    if lastMap then
      hideTiles()
    end
    art:Draw(px, py, mapID, s, turn, C_Map.GetBestMapForUnit("player"))  -- your zone on top
    return
  end
  art:Hide()

  local tilePixels = TILE_YARDS * s
  -- Enough slots to cover the frame's diagonal (it turns), plus the ring of one each side (odd, so the
  -- player's tile is the middle one).
  local w, h = clip:GetWidth(), clip:GetHeight()
  local span = math.ceil(math.sqrt(w * w + h * h) / tilePixels) + 3
  if span % 2 == 0 then
    span = span + 1
  end
  local colF, rowF = 32 - py / TILE_YARDS, 32 - px / TILE_YARDS
  local col, row = math.floor(colF), math.floor(rowF)
  if col ~= lastCol or row ~= lastRow or mapID ~= lastMap or span ~= lastSpan then
    if span ~= lastSpan then
      hideTiles()  -- the slot layout depends on span
    end
    assign(tiles, col, row, span)
    lastCol, lastRow, lastMap, lastSpan = col, row, mapID, span
  end

  -- Positions, by each tile's centre: tile (c, r) spans world x from (32 - r) * T down and y from
  -- (32 - c) * T down, so its centre sits (c + 0.5 - colF) tiles east and (rowF - r - 0.5) tiles north
  -- of the player. Turned: the same rotation as MinimapAreas' project(); each texture turns with it
  -- (SetRotation is counter-clockwise, the map turns clockwise as the player turns left). Rotated tiles
  -- get a pixel of overlap so no hairline shows between them.
  local cos, sin = math.cos(turn), math.sin(turn)
  local size = turn ~= 0 and tilePixels + 1 or tilePixels
  for _, t in pairs(slots) do
    if t:IsShown() then
      local x = (slotCol[t] + 0.5 - colF) * tilePixels
      local y = (rowF - slotRow[t] - 0.5) * tilePixels
      t:SetSize(size, size)
      t:SetRotation(-turn)
      t:ClearAllPoints()
      t:SetPoint("CENTER", holder, "CENTER", x * cos + y * sin, -x * sin + y * cos)
    end
  end
end

---Lines for /bmap tiles: where the player is in the tile grid and what's drawn around them, to
---check the terrain against the minimap.
---@return string[]
function Terrain:Report()
  local lines = {}
  local px, py, _, mapID = UnitPosition("player")
  if not px then
    return { "no position (instance or loading)" }
  end
  local colF, rowF = 32 - py / TILE_YARDS, 32 - px / TILE_YARDS
  lines[#lines + 1] = ("UnitPosition north %.1f, west %.1f, map %s; tile col %.3f, row %.3f"):format(px, py,
    tostring(mapID), colF, rowF)
  local s = clip and scale()
  lines[#lines + 1] = ("view radius %s yd, %s px per yd, rotate %s, facing %s"):format(
    tostring(C_Minimap.GetViewRadius()), s and ("%.3f"):format(s) or "-", tostring(rotating()),
    tostring(GetPlayerFacing()))
  local tiles = mapID and ns.Tiles.maps[mapID]
  if not tiles then
    lines[#lines + 1] = "no terrain data for this map"
    return lines
  end
  local col, row = math.floor(colF), math.floor(rowF)
  for r = row - 1, row + 1 do
    local cells = {}
    for c = col - 1, col + 1 do
      cells[#cells + 1] = ("%d,%d=%s"):format(c, r, tostring(tiles[c * GRID + r] or "-"))
    end
    lines[#lines + 1] = table.concat(cells, "  ")
  end
  return lines
end

---The map's projection for other layers (Group.lua): pixels per yard in `outer`'s units and the turn
---(radians; 0 north-up), or nil before the map exists or without a scale.
---@return number? pixelsPerYard
---@return number? turn
function Terrain:Projection()
  if not clip then
    return nil, nil
  end
  local s = scale()
  if not s then
    return nil, nil
  end
  return s, angle() or 0
end

---One line for /bmap.
---@return string
function Terrain:Describe()
  if not self.active then
    return "terrain off"
  end
  local shown = 0
  for _, t in pairs(slots) do
    if t:IsShown() then
      shown = shown + 1
    end
  end
  return ("terrain (style %s): %d tiles shown, %d loaded, %d failed (data for build %s); map art: %d pieces")
    :format(ns.DB.mapStyle, shown, self.loaded, self.failed, ns.Tiles.build, art and art.drawn or 0)
end

table.insert(ns.Minimap.onActivate, function(outer)
  Terrain.active = true
  clip = CreateFrame("Frame", nil, outer)
  clip:SetAllPoints()
  -- Under Blizzard's minimap by strata: `outer` is one strata below it (Minimap.lua).
  clip:SetClipsChildren(true)
  fill = clip:CreateTexture(nil, "BACKGROUND", nil, 0)
  fill:SetAllPoints()
  fill:SetColorTexture(FILL[1], FILL[2], FILL[3], FILL[4])
  -- The tiles' frame: centred on the minimap (the player), which is centred on `outer`.
  holder = CreateFrame("Frame", nil, clip)
  holder:SetAllPoints()
  art = ns.Art.New(holder)
  clip:SetScript("OnUpdate", update)

  -- The data is for one client build; FileDataIDs rarely change, so a different build only warns.
  local version, buildNumber = GetBuildInfo()
  local running = ("%s.%s"):format(version, buildNumber)
  if running ~= ns.Tiles.build then
    print(("|cffffd100BubbleMap|r: terrain data is for client %s, this is %s; some tiles may be missing.")
      :format(ns.Tiles.build, running))
  end
end)
